#include "entry.h"

#include "codecoremorph_bridge.hpp"
#include "entry.hpp"

namespace bridge = ccm::bridge;

#include <memory>
#include <string>
#include <utility>

namespace {

// An entry of a C# class deriving from Entry: Entry's constructor is protected.
class CSharpEntry final : public ledger::Entry {
public:
    explicit CSharpEntry(std::string memo) : Entry(std::move(memo)) {}
};

}  // namespace

CCM_HANDLE_EXPORTS(ledger_Entry)

CCM_EXPORT ccm_status ledger_Entry_new(const char* memo, ledger_Entry** result) {
    return bridge::guard([&] {
        *result = bridge::to_handle<ledger_Entry>(
            std::make_shared<CSharpEntry>(bridge::str(memo, "memo")));
    });
}

CCM_EXPORT ccm_status ledger_Entry_memo(const ledger_Entry* self, char** result) {
    return bridge::guard([&] { bridge::out_str(result, bridge::from_handle(self)->memo()); });
}

