// The C++ of Ledger.Entry, ported from C# (CodeCoreMorph, D-78).
#ifndef LEDGER_ENTRY_HPP
#define LEDGER_ENTRY_HPP

#include <string>
#include <utility>

namespace ledger {

// A line of the ledger.
class Entry {
public:
    Entry(const Entry&) = delete;
    Entry& operator=(const Entry&) = delete;
    Entry(Entry&&) = delete;
    Entry& operator=(Entry&&) = delete;
    virtual ~Entry() = default;

    const std::string& memo() const { return memo_; }

protected:
    explicit Entry(std::string memo) : memo_(std::move(memo)) {}

private:
    std::string memo_;
};

}  // namespace ledger

#endif

