// The bridge of Ledger.Refund (CodeCoreMorph, D-78).
#include "refund.h"

#include "codecoremorph_bridge.hpp"
#include "refund.hpp"

namespace bridge = ccm::bridge;

#include <memory>

namespace {

// The entry behind a handle as its own class (a hierarchy shares Entry's handle).
template <class T>
std::shared_ptr<const T> as(const ledger_Entry* self) {
    auto object = std::dynamic_pointer_cast<const T>(bridge::from_handle(self));
    if (object == nullptr) {
        throw ccm::InvalidOperationException("the entry is not of the class the export takes");
    }
    return object;
}

}  // namespace

CCM_EXPORT ccm_status ledger_Refund_new(const char* memo, ccm_decimal amount,
                                        ledger_Entry** result) {
    return bridge::guard([&] {
        *result = bridge::to_handle<ledger_Entry>(
            std::make_shared<ledger::Refund>(bridge::str(memo, "memo"), bridge::dec(amount)));
    });
}

CCM_EXPORT ccm_status ledger_Refund_amount(const ledger_Entry* self, ccm_decimal* result) {
    return bridge::guard([&] { *result = bridge::dec(as<ledger::Refund>(self)->amount()); });
}

