using System;
using CodeCoreMorph.Interop;
using Microsoft.CSharp.RuntimeBinder;

namespace Ledger
{
    public static class Labels
    {
        /// <summary>Anything with a memo and an amount, as a line of text.</summary>
        public static string Line(dynamic item)
        {
            // The types the solution passes it (D-88): an export for each kind.
            IntPtr result;
            switch ((object)item)
            {
                case Entry entry:
                    CcmInterop.Check(CcmNative.ledger_Labels_line_Entry(Entry.HandleOf(entry), out result));
                    break;
                case Invoice invoice:
                    CcmInterop.Check(CcmNative.ledger_Labels_line_Invoice(Invoice.HandleOf(invoice), out result));
                    break;
                case null:
                    throw new RuntimeBinderException("Cannot perform runtime binding on a null reference");
                default:
                    throw new NotSupportedException(
                        "Labels.Line is ported for Sale, Refund, PartialRefund, Note and Invoice, the types the solution passes it; not for "
                        + ((object)item).GetType().FullName);
            }
            return CcmInterop.TakeString(result);
        }
    }
}

