namespace Ledger
{
    /// <summary>A running count: whole units until an amount comes in.</summary>
    public sealed class Tally
    {
        internal readonly ledger_TallyHandle Handle;

        public Tally()
        {
            CcmInterop.Check(CcmNative.ledger_Tally_new(out Handle));
        }

        public void Add(int units)
        {
            CcmInterop.Check(CcmNative.ledger_Tally_add_int(Handle, units));
        }

        public void Add(decimal amount)
        {
            CcmInterop.Check(CcmNative.ledger_Tally_add_decimal(Handle, CcmDecimal.From(amount)));
